import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.FileDialog;
import org.eclipse.swt.widgets.Shell;

public class TestClass {
    public void testMethod() {
        Shell shell = new Shell(Display.getDefault());
        FileDialog dialog = new FileDialog(shell, SWT.OPEN);
        FileDialog saveDialog = new FileDialog(shell, SWT.SAVE | SWT.MULTI);
    }
}

afterExample:
import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.FileDialog;
import org.eclipse.swt.widgets.Shell;

public class TestClass {
    public void testMethod() {
        Shell shell = new Shell(Display.getDefault());
        FileDialog dialog = new FileDialog(shell, SWT.OPEN | org.eclipse.swt.SWT.SHEET);
        FileDialog saveDialog = new FileDialog(shell, SWT.SAVE | SWT.MULTI | org.eclipse.swt.SWT.SHEET);
    }
}

