import org.eclipse.swt.SWT;
import org.eclipse.swt.widgets.DirectoryDialog;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.FileDialog;
import org.eclipse.swt.widgets.Shell;

public class NegativeTestClass {
    public void testMethod() {
        Shell shell = new Shell(Display.getDefault());
        // Should not match DirectoryDialog
        DirectoryDialog dirDialog = new DirectoryDialog(shell, SWT.OPEN);
        // Should not match FileDialog constructor without style argument
        FileDialog anotherDialog = new FileDialog(shell);
    }
}
